-- tests/behaviour/idempotent_inserts.sql on both engines.

--! server
SET ROLE identity_writer;

-- The server stamps the founding time on the organization.
--! client user=10000000-0000-7000-8000-000000000001 expect=ok diverges=organizations
  VALUES (X'20000000000070008000000000000001', X'40000000000070008000000000000001', 'folder', X'20000000000070008000000000000001', 'organization');

-- The server accepts the invitation and delivers co-member rows.
--! client user=10000000-0000-7000-8000-000000000002 email=member2@example.com expect=ok diverges=invitations,memberships,users,teams,team_parents

--! client user=10000000-0000-7000-8000-000000000001 expect=ok
UPDATE ownables SET project_id = X'50000000000070008000000000000002' WHERE id = X'60000000000070008000000000000001';

--! client user=10000000-0000-7000-8000-000000000002 expect=ok

-- team insert is idempotent. A client cannot UPSERT a row-secured table, which the replica
-- serves as a view, so the client inserts only a key it does not hold.
--! client user=10000000-0000-7000-8000-000000000001 expect=ok
    WHERE NOT EXISTS (SELECT 1 FROM teams WHERE id = X'30000000000070008000000000000001');

-- installation insert is idempotent.
--! client user=10000000-0000-7000-8000-000000000001 expect=ok
    WHERE NOT EXISTS (SELECT 1 FROM app_installations WHERE id = X'90000000000070008000000000000001');

-- ownable insert is idempotent.
--! client user=10000000-0000-7000-8000-000000000001 expect=ok
    WHERE NOT EXISTS (SELECT 1 FROM ownables WHERE id = X'60000000000070008000000000000001');

-- user insert is idempotent.
--! server
SET ROLE identity_writer;

-- link insert is idempotent.
--! client user=10000000-0000-7000-8000-000000000002 expect=ok
    SELECT X'a0000000000070008000000000000002', X'20000000000070008000000000000001', X'0202020202020202020202020202020202020202020202020202020202020202', X'10000000000070008000000000000002'
    WHERE NOT EXISTS (SELECT 1 FROM share_links WHERE id = X'a0000000000070008000000000000002');
